const mig3 = `-- Records who made each attempt (visitor level), so the teacher's own test plays
-- stay off the class leaderboard. Existing rows get '' and are filtered by name below.
ALTER TABLE attempts ADD COLUMN visitor_level TEXT NOT NULL DEFAULT '';
`;

const actor = `// The quiz's server half: this week's questions, scoring an attempt, and the week's leaderboard.
// Built by a colleague in the bench; students take the quiz every week.
const sql = use('sql');

// Visitor levels that are staff (the teacher, or the owner of the app).
const STAFF_LEVELS = ['admin', 'owner', 'teacher'];
// Names that must never appear on a class board: staff, and the placeholder used by
// attempts recorded before students typed their own name.
const NOT_A_STUDENT = ['admin', 'administrator', 'teacher', 'student', 'anonymous'];

// The week students are answering right now (the latest week that has questions).
function currentWeek() {
  const row = sql.one('SELECT max(week) AS week FROM questions');
  return row && row.week ? row.week : null;
}

// A leaderboard shows first names only, whatever the roster or login gave us:
// "Ava Nguyen" -> Ava, "Nguyen, Ava" -> Ava, "ava.nguyen@school.org" -> Ava.
// Returns '' when there is nothing usable, so callers can refuse an empty name.
function cleanFirstName(raw) {
  let s = String(raw == null ? '' : raw).trim();
  if (!s) return '';
  if (s.includes('@')) s = s.slice(0, s.indexOf('@')).replace(/[._-]+/g, ' ');
  else if (s.includes(',')) s = s.split(',').pop();
  const first = (s.split(/\\s+/)[0] || '').replace(/[^A-Za-z'-]/g, '').slice(0, 20);
  if (!first) return '';
  // "AVA" -> "Ava", but "McDonald" and "O'Brien" keep their shape.
  const rest = first.slice(1);
  const r = rest === rest.toUpperCase() ? rest.toLowerCase() : rest;
  return first.charAt(0).toUpperCase() + r;
}

function isStaff(ctx) {
  const level = String((ctx.visitor && ctx.visitor.level) || '').toLowerCase();
  return STAFF_LEVELS.indexOf(level) !== -1;
}

defineActor({
  actions: {
    questions: {
      requires: 'view',
      run(ctx) {
        // the latest week that has questions
        const w = sql.one('SELECT max(week) AS week FROM questions');
        return sql.all('SELECT id, text, choices FROM questions WHERE week = ? ORDER BY id', w.week)
          .map((q) => ({ id: q.id, text: q.text, choices: JSON.parse(q.choices) }));
      },
    },
    submit: {
      requires: 'interact',
      run(ctx, { answers, name }) {
        // students type their own first name; we store that, and nothing else
        const student = cleanFirstName(name);
        if (!student) throw new Error('Please type your first name.');
        const w = currentWeek();
        const qs = sql.all('SELECT id, answer FROM questions WHERE week = ?', w);
        let score = 0;
        for (const q of qs) if (answers && answers[q.id] === q.answer) score++;
        const level = String((ctx.visitor && ctx.visitor.level) || '');
        sql.run(
          'INSERT INTO attempts (week, student, score, at, visitor_level) VALUES (?, ?, ?, ?, ?)',
          w, student, score, Date.now(), level
        );
        return { score, of: qs.length, name: student };
      },
    },
    leaderboard: {
      requires: 'view',
      run(ctx) {
        const w = currentWeek();
        const of = sql.one('SELECT count(*) AS n FROM questions WHERE week = ?', w).n;
        // one row per student: their best score that week, whoever reached it first listed first.
        // staff plays, and attempts with no student name, never count.
        const rows = sql.all(
          "SELECT student, max(score) AS score, min(at) AS at FROM attempts WHERE week = ?" +
            " AND lower(coalesce(visitor_level, '')) NOT IN ('admin', 'owner', 'teacher')" +
            " AND lower(trim(student)) NOT IN ('admin', 'administrator', 'teacher', 'student', 'anonymous')" +
            ' GROUP BY student ORDER BY score DESC, at ASC',
          w
        ).slice(0, 10);
        return {
          week: w,
          of,
          entries: rows.map((r, i) => ({ rank: i + 1, name: r.student, score: r.score })),
        };
      },
    },
  },
});
`;

