const actor = `// The bakery's server side: the weekly cut-off, the orders, the bakers' list.

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']

function two(n: number) { return n < 10 ? '0' + n : String(n) }

function dayKey(d: Date) {
  return d.getFullYear() + '-' + two(d.getMonth() + 1) + '-' + two(d.getDate())
}

function dayLabel(d: Date) {
  return WEEKDAYS[d.getDay()] + ' ' + d.getDate() + ' ' + MONTHS[d.getMonth()]
}

function addDays(d: Date, n: number) {
  const x = new Date(d.getTime())
  x.setDate(x.getDate() + n)
  return x
}

// The next Thursday at 23:59 is the cut-off; bread is baked the Saturday after it.
function orderWindow(now: Date) {
  const toThu = (4 - now.getDay() + 7) % 7
  let deadline = addDays(now, toThu)
  deadline.setHours(23, 59, 0, 0)
  if (now.getTime() > deadline.getTime()) deadline = addDays(deadline, 7)
  const bake = addDays(deadline, 2)
  return { deadline, bake, is_open: now.getTime() <= deadline.getTime() }
}

// This week's bake: the coming Saturday (today, if today is Saturday).
function thisBake(now: Date) {
  return addDays(now, (6 - now.getDay() + 7) % 7)
}

