const week = `// When ordering opens and closes, and which Friday each order is baked for.

export interface OrderWindow {
  open: boolean
  forDate: string
  forLabel: string
  closesAt: number
  opensAt: number
  opensLabel: string
}

export function nowMs(): number {
  // ?now=2026-11-20T09:00 lets you look at the page as it will be on another day.
  const raw = new URLSearchParams(location.search).get('now')
  if (raw) {
    const t = Date.parse(raw)
    if (Number.isFinite(t)) return t
  }
  return Date.now()
}

function midnight(d: Date): Date {
  const x = new Date(d.getTime())
  x.setHours(0, 0, 0, 0)
  return x
}

export function isoOf(d: Date): string {
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  return \\\`\\\${d.getFullYear()}-\\\${m}-\\\${day}\\\`
}

export function addDays(d: Date, n: number): Date {
  const x = new Date(d.getTime())
  x.setDate(x.getDate() + n)
  return x
}

export function shiftIso(iso: string, days: number): string {
  const [y, m, d] = iso.split('-').map(Number)
  return isoOf(addDays(new Date(y, m - 1, d), days))
}

export function isoMidnight(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number)
  return new Date(y, m - 1, d)
}

export function forLabel(iso: string): string {
  return isoMidnight(iso).toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long' })
}

// Ordering runs Monday to Thursday and closes on Thursday at midnight.
// Friday to Sunday the ovens are busy, so the form is closed and the next
// window opens on Monday, for the Friday after.
export function orderWindow(now: number): OrderWindow {
  const d = midnight(new Date(now))
  const day = d.getDay()
  if (day >= 1 && day <= 4) {
    const thursday = addDays(d, 4 - day)
    const friday = addDays(thursday, 1)
    return {
      open: true,
      forDate: isoOf(friday),
      forLabel: forLabel(isoOf(friday)),
      closesAt: friday.getTime() - 1,
      opensAt: -1,
      opensLabel: '',
    }
  }
  const toMonday = day === 5 ? 3 : day === 6 ? 2 : 1
  const monday = addDays(d, toMonday)
  const friday = addDays(monday, 4)
  return {
    open: false,
    forDate: isoOf(friday),
    forLabel: forLabel(isoOf(friday)),
    closesAt: friday.getTime() - 1,
    opensAt: monday.getTime(),
    opensLabel: monday.toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long' }),
  }
}

// The batch the kitchen is working on: while ordering is open that is the
// coming Friday, while it is closed it is the Friday just gone.
export function bakeFriday(now: number): string {
  const w = orderWindow(now)
  return w.open ? w.forDate : shiftIso(w.forDate, -7)
}
`;

