// page's types come from them too (slop types writes actions.d.ts).
const sql = use('sql')

// Orders are taken Monday through Thursday night. Friday morning Maya
// reads the list and bakes, so after Thursday the form closes for the week.
function ordersOpen(now = Date.now()): boolean {
  const day = new Date(now).getUTCDay() // 0 = Sunday ... 6 = Saturday
  return day >= 1 && day <= 4
}

const OPEN_NOTE = 'Fresh bread for the weekend! Orders close Thursday night.'
const CLOSED_NOTE = 'Orders are closed for the week — see you next week!'

defineActor({
  actions: {
    orders: defineAction({
      requires: 'view',
      args: { type: 'object', properties: {} },
      result: {
        type: 'object',
        required: ['open', 'note', 'rows', 'totals'],
        properties: {
          open: { type: 'boolean' },
          note: { type: 'string' },
          rows: {
            type: 'array',
            items: {
              type: 'object',
              required: ['id', 'name', 'phone', 'sourdough', 'rye', 'rolls', 'at'],
              properties: {
                id: { type: 'integer' },
                name: { type: 'string' },
                phone: { type: 'string' },
                sourdough: { type: 'integer' },
                rye: { type: 'integer' },
                rolls: { type: 'integer' },
                at: { type: 'integer' },
              },
            },
          },
          totals: {
            type: 'object',
            required: ['sourdough', 'rye', 'rolls'],
            properties: {
              sourdough: { type: 'integer' },
              rye: { type: 'integer' },
              rolls: { type: 'integer' },
            },
          },
        },
      },
      run(ctx) {
        const rows = sql.all(
          'SELECT id, name, phone, sourdough, rye, rolls, at FROM orders ORDER BY at DESC, id DESC LIMIT 200'
        )
        const totals = { sourdough: 0, rye: 0, rolls: 0 }
        for (const r of rows) {
          totals.sourdough += r.sourdough
          totals.rye += r.rye
          totals.rolls += r.rolls
        }
        const open = ordersOpen()
        return { open, note: open ? OPEN_NOTE : CLOSED_NOTE, rows, totals }
      },
    }),
    order: defineAction({
      requires: 'interact',
      args: {
        type: 'object',
        required: ['name', 'phone', 'sourdough', 'rye', 'rolls'],
        additionalProperties: false,
        properties: {
          name: { type: 'string', minLength: 1, maxLength: 80 },
          phone: { type: 'string', minLength: 1, maxLength: 30 },
          sourdough: { type: 'integer', minimum: 0, maximum: 20 },
          rye: { type: 'integer', minimum: 0, maximum: 20 },
          rolls: { type: 'integer', minimum: 0, maximum: 20 },
        },
      },
      result: { type: 'object', required: ['ok'], properties: { ok: { type: 'boolean' } } },
      run(ctx, a) {
        if (!ordersOpen()) ctx.fail('policy', 'Orders are closed for the week')
        const name = a.name.trim()
        const phone = a.phone.trim()
        if (!name) ctx.fail('invalid_argument', 'name is empty')
        if (!phone) ctx.fail('invalid_argument', 'phone is empty')
        if (a.sourdough + a.rye + a.rolls === 0) ctx.fail('invalid_argument', 'pick at least one bread')
        sql.run(
          'INSERT INTO orders (name, phone, sourdough, rye, rolls, at) VALUES (?, ?, ?, ?, ?, ?)',
          name, phone, a.sourdough, a.rye, a.rolls, Date.now()
        )
        return { ok: true }
      },
    }),
  },
})
`)

