  ['sourdough', 'sourdough'],
  ['rye', 'rye'],
  ['rolls', 'cinnamon rolls'],
]

function counts(c: { sourdough: number; rye: number; rolls: number }): string {
  const parts = breads.filter(([k]) => c[k] > 0).map(([k, label]) => c[k] + ' ' + label)
  return parts.length ? parts.join(', ') : 'no breads'
}

let unlocked = false // Maya has typed her secret word this visit

// What everyone sees: the friendly weekly tally, no names or phones.
