  if (!slop) return
  const res = await slop.actions.orders({})
  status.textContent = res.note
  const fields = form.querySelectorAll('input, button') as NodeListOf<HTMLInputElement | HTMLButtonElement>
  for (const f of fields) f.disabled = !res.open
  week.textContent =
    res.count === 0
      ? 'No orders yet — yours could be the first!'
      : 'So far this week: ' + res.count + (res.count === 1 ? ' order — ' : ' orders — ') + counts(res.totals) + '.'
