const actorSrc = `// The app's server half: the actions the page calls. Cards live in SQL
// (sql/002_cards.sql): the database is the source of truth, the page only
// asks. Each action declares the JSON Schema of its arguments (checked
// before run: a wrong shape is refused) and of its result; defineAction
// types the action's code from them, and the page's slop.actions are
// typed from them (slop types writes actions.d.ts).
import type { Card, ColumnId } from './types.ts'

const sql = use('sql')

// The JSON Schema of one card, shared by the actions' result schemas.
const cardSchema = {
  type: 'object',
  required: ['id', 'title', 'owner', 'column'],
  properties: {
    id: { type: 'integer' },
    title: { type: 'string' },
    owner: { type: 'string' },
    column: { type: 'string', enum: ['todo', 'doing', 'done'] },
  },
}

defineActor({
  actions: {
    // Every card, oldest first.
    list: defineAction({
      requires: 'view',
      args: { type: 'object', properties: {} },
      result: { type: 'array', items: cardSchema },
      run() {
        return sql.all('SELECT id, title, owner, status AS "column" FROM cards ORDER BY created_at, id') as Card[]
      },
    }),
    // Add a card to a column. Owner falls back to the visitor's name.
    add: defineAction({
      requires: 'interact',
      args: {
        type: 'object',
        required: ['title', 'owner', 'column'],
        additionalProperties: false,
        properties: {
          title: { type: 'string', minLength: 1, maxLength: 200 },
          owner: { type: 'string', maxLength: 80 },
          column: { type: 'string', enum: ['todo', 'doing', 'done'] },
        },
      },
      result: cardSchema,
      run(ctx, { title, owner, column }: { title: string; owner: string; column: ColumnId }) {
        const t = title.trim()
        const o = owner.trim() || ctx.visitor.name || 'someone'
        if (!t) ctx.fail('invalid_argument', 'title is empty')
        sql.run('INSERT INTO cards (title, owner, status, created_at) VALUES (?, ?, ?, ?)', t, o, column, Date.now())
        const card = sql.one('SELECT id, title, owner, status AS "column" FROM cards WHERE id = last_insert_rowid()') as Card | null
        if (!card) ctx.fail('invalid_argument', 'could not read the new card')
        // ctx.fail rejects the call; the cast is only for TS (fail returns void).
        return card as Card
      },
    }),
    // Move a card to another column.
    move: defineAction({
      requires: 'interact',
      args: {
        type: 'object',
        required: ['id', 'column'],
        additionalProperties: false,
        properties: {
          id: { type: 'integer' },
          column: { type: 'string', enum: ['todo', 'doing', 'done'] },
        },
      },
      result: cardSchema,
      run(ctx, { id, column }) {
        // A no-op update for a missing id leaves nothing to select: not_found.
        sql.run('UPDATE cards SET status = ? WHERE id = ?', column, id)
        const card = sql.one('SELECT id, title, owner, status AS "column" FROM cards WHERE id = ?', id) as Card | null
        if (!card) ctx.fail('not_found', 'no card #' + id)
        // ctx.fail rejects the call; the cast is only for TS (fail returns void).
        return card as Card
      },
    }),
  },
})
`;
