export const LIST_SQL = \`
SELECT id, destination, weight_kg AS weightKg, status, date
FROM shipments
ORDER BY date DESC, id DESC\`

// One row per status the CHECK constraint allows, so a status with no
// shipments shows 0 instead of vanishing.
export const COUNT_BY_STATUS_SQL = \`
SELECT s.status AS status, COUNT(x.id) AS n
FROM (SELECT 'packed' AS status, 1 AS ord
      UNION ALL SELECT 'shipped', 2
      UNION ALL SELECT 'delivered', 3) AS s
LEFT JOIN shipments AS x ON x.status = s.status
GROUP BY s.status, s.ord
ORDER BY s.ord\`

// "Shipped this week": status shipped or delivered, date Monday through
// Sunday INCLUSIVE. Dates are 'YYYY-MM-DD', so >= Monday and <= Sunday is
// the whole week. SUM is rounded to 2 decimals in SQL (kg with 0.01 grams
// is nonsense, and floats like 12.4 + 27.3 have noise at the 15th digit).
export const WEEK_WEIGHT_SQL = \`
SELECT COUNT(*) AS n,
       COALESCE(ROUND(SUM(weight_kg), 2), 0) AS kg
FROM shipments
WHERE status IN ('shipped', 'delivered')
  AND date >= ?   -- Monday of the week
  AND date <= ?   -- Sunday of the week\`
`;

const week = `// "This week" = Monday 00:00 through Sunday 23:59, in UTC. Our dates are
// plain 'YYYY-MM-DD' strings with no zone, so the week is computed once
// here, in UTC, and handed back to the page: the page shows which week a
// number is for, so nothing is hidden. Change the two getUTC* calls to
// getFullYear/getMonth/getDate if you would rather use server local time.
const DAY = 86_400_000;

function iso(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export function weekBounds(now: Date = new Date()): { today: string; start: string; end: string } {
  const today = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  const sinceMonday = (today.getUTCDay() + 6) % 7; // Monday = 0 … Sunday = 6
  const start = new Date(today.getTime() - sinceMonday * DAY);
  const end = new Date(start.getTime() + 6 * DAY);
  return { today: iso(today), start: iso(start), end: iso(end) };
}
`;

