const helper = `function first(name: string): string {
  return name.trim().split(/\\s+/)[0] ?? ''
}

// Move waitlisted people into a shift that now has room (oldest first).
function promoteWaiting(shiftId: number): void {
  for (;;) {
    const shift = sql.one('SELECT needed FROM shifts WHERE id = ?', shiftId) as { needed: number } | null
    if (!shift) return
    const filled = (sql.one(
      "SELECT count(*) AS n FROM signups WHERE shift_id = ? AND status = 'signed'", shiftId,
    ) as { n: number }).n
    if (filled >= shift.needed) return
    const next = sql.one(
      "SELECT id FROM signups WHERE shift_id = ? AND status = 'waitlist' ORDER BY created_at, id LIMIT 1",
      shiftId,
    ) as { id: number } | null
    if (!next) return
    sql.run("UPDATE signups SET status = 'signed' WHERE id = ?", next.id)
  }
}`

