const newCard = `function coordinatorCard(s: Roster): HTMLElement {
  const card = document.createElement('article')
  card.className = 'shift'
  card.dataset.id = String(s.id)

  const h2 = document.createElement('h2')
  h2.textContent = s.task
  const when = document.createElement('p')
  when.className = 'when'
  when.textContent = fmtDate(s.date) + ' · starts ' + fmtTime(s.start)
  const signed = s.signups.filter((v) => v.status === 'signed')
  const waiting = s.signups.filter((v) => v.status === 'waitlist')
  const spots = document.createElement('p')
  spots.className = 'spots'
  spots.textContent = signed.length + ' of ' + s.needed + ' spots filled'

  const who = document.createElement('p')
  who.className = 'who'
  who.textContent = signed.length
    ? 'On the shift: ' + signed.map((v) => v.name + ' · ' + v.phone).join(' | ')
    : 'No volunteers yet.'
  const w = document.createElement('p')
  w.className = 'who waitlist'
  w.textContent = waiting.length ? 'Waiting list: ' + waiting.map((v) => v.name + ' · ' + v.phone).join(' | ') : ''
  if (!waiting.length) w.hidden = true

  // Editable copy of the shift's details, hidden until "Edit" is pressed.
  const editForm = document.createElement('form')
  editForm.className = 'edit'
  editForm.hidden = true
  const fDate = document.createElement('input')
  fDate.name = 'date'; fDate.type = 'date'; fDate.value = s.date; fDate.required = true
  const fStart = document.createElement('input')
  fStart.name = 'start'; fStart.type = 'time'; fStart.value = s.start; fStart.required = true
  const fTask = document.createElement('input')
  fTask.name = 'task'; fTask.value = s.task; fTask.required = true; fTask.maxLength = 100
  const fNeeded = document.createElement('input')
  fNeeded.name = 'needed'; fNeeded.type = 'number'; fNeeded.value = String(s.needed)
  fNeeded.min = '1'; fNeeded.max = '50'; fNeeded.required = true
  const fSave = document.createElement('button')
  fSave.type = 'submit'
  fSave.textContent = 'Save changes'
  editForm.append(fDate, fStart, fTask, fNeeded, fSave)

  const tools = document.createElement('p')
  tools.className = 'tools'
  const editBtn = document.createElement('button')
  editBtn.type = 'button'
  editBtn.textContent = 'Edit'
  editBtn.addEventListener('click', () => {
    editForm.hidden = !editForm.hidden
    if (!editForm.hidden) fNeeded.focus()
  })
  const delBtn = document.createElement('button')
  delBtn.type = 'button'
  delBtn.className = 'danger'
  delBtn.textContent = 'Delete shift'
  delBtn.addEventListener('click', async () => {
    // Two taps to delete: the first just arms the button.
    if (delBtn.dataset.armed !== '1') {
      delBtn.dataset.armed = '1'
      delBtn.textContent = 'Really delete?'
      window.setTimeout(() => {
        delBtn.dataset.armed = ''
        delBtn.textContent = 'Delete shift'
      }, 4000)
      return
    }
    delBtn.disabled = true
    try {
      await slop!.actions.deleteShift({ code: code!, id: s.id })
