      delBtn.disabled = false
      note(coordMsg, err?.message || 'Could not delete the shift.')
      return
    }
    await showRoster()
  })
  tools.append(editBtn, delBtn)

  card.append(h2, when, spots, who, w, tools, editForm)
  return card
}`

